/// Normalizes a 2D boolean patch (row-major: th rows, tw columns) into a 14x14 float canvas.
pub fn normalize_glyph(patch: &[bool], tw: usize, th: usize) -> [f32; CANON_DIM * CANON_DIM] {
    let mut canvas = [0.0f32; CANON_DIM * CANON_DIM];
    if tw == 0 || th == 0 {
        return canvas;
    }

    // Find tight bounding box
    let mut min_y = th;
    let mut max_y = 0;
    let mut min_x = tw;
    let mut max_x = 0;
    let mut found = false;

    for y in 0..th {
        for x in 0..tw {
            if patch[y * tw + x] {
                found = true;
                if y < min_y { min_y = y; }
                if y > max_y { max_y = y; }
                if x < min_x { min_x = x; }
                if x > max_x { max_x = x; }
            }
        }
    }

    if !found {
        return canvas;
    }

    let tight_h = max_y - min_y + 1;
    let tight_w = max_x - min_x + 1;

    let max_dim = tight_h.max(tight_w) as f32;
    let scale = 10.0f32 / max_dim;
    let nw = (tight_w as f32 * scale).round().max(1.0) as usize;
    let nh = (tight_h as f32 * scale).round().max(1.0) as usize;

    let ox = (CANON_DIM.saturating_sub(nw)) / 2;
    let oy = (CANON_DIM.saturating_sub(nh)) / 2;

    for y in 0..nh {
        let sy = (y as f32 + 0.5) * (tight_h as f32 / nh as f32) - 0.5;
        let y0 = sy.floor().max(0.0) as usize;
        let y1 = (y0 + 1).min(tight_h.saturating_sub(1));
        let fy = (sy - sy.floor()).clamp(0.0, 1.0);

        for x in 0..nw {
            let sx = (x as f32 + 0.5) * (tight_w as f32 / nw as f32) - 0.5;
            let x0 = sx.floor().max(0.0) as usize;
            let x1 = (x0 + 1).min(tight_w.saturating_sub(1));
            let fx = (sx - sx.floor()).clamp(0.0, 1.0);

            let v00 = if patch[(min_y + y0) * tw + (min_x + x0)] { 1.0f32 } else { 0.0f32 };
            let v01 = if patch[(min_y + y0) * tw + (min_x + x1)] { 1.0f32 } else { 0.0f32 };
            let v10 = if patch[(min_y + y1) * tw + (min_x + x0)] { 1.0f32 } else { 0.0f32 };
            let v11 = if patch[(min_y + y1) * tw + (min_x + x1)] { 1.0f32 } else { 0.0f32 };

            let top = v00 * (1.0 - fx) + v01 * fx;
            let bot = v10 * (1.0 - fx) + v11 * fx;
            let val = top * (1.0 - fy) + bot * fy;

            let cy = oy + y;
            let cx = ox + x;
            if cy < CANON_DIM && cx < CANON_DIM {
                canvas[cy * CANON_DIM + cx] = val;
            }
        }
    }

    canvas
}

/// Runs forward pass on normalized 14x14 patch and returns (predicted_digit, confidence).
pub fn predict_normalized(feat: &[f32; CANON_DIM * CANON_DIM]) -> (u32, f32) {
    // Layer 1: 196 -> 64 (ReLU)
    let mut h1 = [0.0f32; 64];
    for j in 0..64 {
        let mut sum = B1[j];
        for i in 0..196 {
            sum += feat[i] * W1[i * 64 + j];
        }
        h1[j] = sum.max(0.0);
    }

    // Layer 2: 64 -> 32 (ReLU)
    let mut h2 = [0.0f32; 32];
    for j in 0..32 {
        let mut sum = B2[j];
        for i in 0..64 {
            sum += h1[i] * W2[i * 32 + j];
        }
        h2[j] = sum.max(0.0);
    }

    // Layer 3: 32 -> 10 (Logits)
    let mut logits = [0.0f32; 10];
    let mut max_l = f32::NEG_INFINITY;
    for j in 0..10 {
        let mut sum = B3[j];
        for i in 0..32 {
            sum += h2[i] * W3[i * 10 + j];
        }
        logits[j] = sum;
        if sum > max_l {
            max_l = sum;
        }
    }

    // Softmax
    let mut sum_exp = 0.0f32;
    let mut probs = [0.0f32; 10];
    for j in 0..10 {
        let p = (logits[j] - max_l).exp();
        probs[j] = p;
        sum_exp += p;
    }

    let mut best_digit = 0;
    let mut best_prob = 0.0f32;
    for j in 0..10 {
        let prob = if sum_exp > 0.0 { probs[j] / sum_exp } else { 0.0 };
        if prob > best_prob {
            best_prob = prob;
            best_digit = j as u32;
        }
    }

    (best_digit, best_prob)
}

/// Convenience function: normalizes a raw binary patch and predicts the digit.
pub fn predict_digit(patch: &[bool], tw: usize, th: usize) -> (u32, f32) {
    let feat = normalize_glyph(patch, tw, th);
    predict_normalized(&feat)
}
